import os
from google.cloud import monitoring_v3

def filter_metric_dimensions(payload, config=None):
    config = config or {}
    client = monitoring_v3.MetricServiceClient()
    project_id = config.get("project_id") or os.environ.get("GOOGLE_CLOUD_PROJECT") or os.environ.get("GCLOUD_PROJECT")
    if not project_id:
        raise ValueError("Missing GCP project_id. Set config['project_id'] or GOOGLE_CLOUD_PROJECT.")
    project_name = f"projects/{project_id}"

    metric_type = payload.get("metric_type")
    if not metric_type:
        raise ValueError("payload['metric_type'] is required")

    filter_parts = [f'metric.type = "{metric_type}"']

    metric_labels = payload.get("metric_labels") or {}
    for key, value in metric_labels.items():
        filter_parts.append(f'metric.labels.{key} = "{value}"')

    resource_type = payload.get("resource_type")
    if resource_type:
        filter_parts.append(f'resource.type = "{resource_type}"')

    resource_labels = payload.get("resource_labels") or {}
    for key, value in resource_labels.items():
        filter_parts.append(f'resource.labels.{key} = "{value}"')

    time_series_filter = " AND ".join(filter_parts)

    interval = monitoring_v3.TimeInterval()
    interval.end_time.FromSeconds(int(payload.get("end_time", 0)) or int(__import__("time").time()))
    interval.start_time.FromSeconds(int(payload.get("start_time", 0)) or (int(__import__("time").time()) - int(payload.get("lookback_seconds", 3600))))

    aggregation = monitoring_v3.Aggregation()
    alignment_period = int(payload.get("alignment_period_seconds", 60))
    aggregation.alignment_period.seconds = alignment_period
    aggregation.per_series_aligner = monitoring_v3.Aggregation.Aligner.ALIGN_MEAN

    result = []
    for series in client.list_time_series(
        request={
            "name": project_name,
            "filter": time_series_filter,
            "interval": interval,
            "aggregation": aggregation,
            "view": monitoring_v3.ListTimeSeriesRequest.TimeSeriesView.FULL,
        }
    ):
        points = []
        for point in series.points:
            points.append(
                {
                    "interval": {
                        "start_time": point.interval.start_time.ToDatetime().isoformat()
                        if point.interval.start_time.seconds or point.interval.start_time.nanos
                        else None,
                        "end_time": point.interval.end_time.ToDatetime().isoformat()
                        if point.interval.end_time.seconds or point.interval.end_time.nanos
                        else None,
                    },
                    "value": point.value.WhichOneof("value"),
                    "number_value": point.value.double_value or point.value.int64_value or point.value.uint64_value,
                    "string_value": point.value.string_value or None,
                    "bool_value": point.value.bool_value if point.value.WhichOneof("value") == "bool_value" else None,
                }
            )

        result.append(
            {
                "metric": dict(series.metric.labels),
                "resource": dict(series.resource.labels),
                "metric_type": series.metric.type,
                "resource_type": series.resource.type,
                "points": points,
            }
        )
    return result
